"use client";
/**
 * 3D scene (PRD §19.2 #2, §19.4): fixed hub geometry from Blender (public/hub.glb), camera frusta from the mounting
 * plan, scan read points, and the typed trace from the backend. Nothing here is generated by a model.
 * Site Z-up -> renderer Y-up uses the backend's matrix (lib/frames).
 */
import { describeScan } from "@/lib/scans";
import { Canvas, useThree, type ThreeEvent } from "@react-three/fiber";
import { Line, OrbitControls, useGLTF } from "@react-three/drei";
import { Suspense, useEffect, useMemo, useRef, useState, useSyncExternalStore, type RefObject } from "react";
import * as THREE from "three";
import type { OrbitControls as OrbitControlsImpl } from "three-stdlib";
import { floorFootprint, frustumCorners, siteToRenderer, type Vec3 } from "@/lib/frames";
import { HUB, centroid, hubZone, scanPoint, type HubCamera } from "@/lib/hub";
import { buildTrace } from "@/lib/trace";
import { routeLink, surfaceHeight } from "@/lib/topology";
import type { ReplayPoint } from "@/lib/types";
import { fmtTime } from "@/lib/time";
import { useWorkspace } from "./context";
import { SpoorLoader } from "@/components/brand/SpoorLoader";
import { useResource } from "@/lib/api";
import { buildCheckpoints, type CaseRecord, type Checkpoint } from "@/lib/checkpoints";
import "./workspace.css"; // the scene, labels, compass and tools (was loaded by the old workspace page)

const HIDE = /^(roof|roof_lights|roof_services|highbay|mounted_fluorescent|wall_S|wall_E|structure)/;
const r3 = (p: Vec3) => new THREE.Vector3(...siteToRenderer(p));

const RM = "(prefers-reduced-motion: reduce)";
function usePrefersReducedMotion() {
  return useSyncExternalStore(
    (cb) => { const m = window.matchMedia(RM); m.addEventListener("change", cb); return () => m.removeEventListener("change", cb); },
    () => window.matchMedia(RM).matches,
    () => false,
  );
}

function HubModel({ onReady }: { onReady: () => void }) {
  const { scene } = useGLTF("/hub.glb", "/draco/");
  const model = useMemo(() => {
    const s = scene.clone(true);
    s.traverse((o) => {
      if (HIDE.test(o.name)) o.visible = false;
      const m = o as THREE.Mesh;
      if (m.isMesh && /^(floor_slab|ground|yard_)/.test(o.name)) {
        // a neutral floor keeps evidence colours legible; the floor's look is not evidence
        m.material = new THREE.MeshStandardMaterial({ color: o.name === "floor_slab" ? "#5d6268" : "#3a3e43", roughness: 0.95 });
      }
      if (m.isMesh) {
        m.raycast = () => {}; // geometry is context, not a click target
        const mats = Array.isArray(m.material) ? m.material : [m.material];
        mats.forEach((mat) => {
          const sm = mat as THREE.MeshStandardMaterial;
          if (sm.emissive) sm.emissiveIntensity = Math.min(sm.emissiveIntensity ?? 0, 0.2);
        });
      }
    });
    return s;
  }, [scene]);
  useEffect(onReady, [onReady]);
  return <primitive object={model} />;
}

function ZoneOverlay() {
  const shapes = useMemo(() => HUB.zones.filter((z) => z.id !== "Z14").map((z) => ({
    id: z.id,
    name: z.name,
    lines: z.polygons.map((poly) => [...poly, poly[0]].map(([x, y]) => r3([x, y, 0.04]))),
    c: centroid(z.polygons[0]),
  })), []);
  const blind = useMemo(() => [...HUB.blind_corner.polygon, HUB.blind_corner.polygon[0]]
    .map(([x, y]) => r3([x, y, 0.06])), []);
  return (
    <group>
      {shapes.map((s) => s.lines.map((pts, i) => (
        <Line key={`${s.id}-${i}`} points={pts} color="#9aa4ad" lineWidth={1} transparent opacity={0.45} />
      )))}
      <Line points={blind} color="#f87171" lineWidth={1.5} dashed dashSize={0.6} gapSize={0.4} />
    </group>
  );
}

function CameraCone({ cam, lit, covered }: { cam: HubCamera; lit: boolean; covered: boolean }) {
  const apex = r3([cam.position_m[0], cam.position_m[1], cam.height_m]);
  const corners = frustumCorners(cam, lit ? 40 : 18).map(r3);
  const foot = useMemo(() => {
    const f = floorFootprint(cam, 40);
    return [...f, f[0]].map(([x, y]) => r3([x, y, 0.05]));
  }, [cam]);
  const color = lit ? "#a99bff" : covered ? "#c6ccd2" : "#59616a";
  const opacity = lit ? 0.95 : covered ? 0.4 : 0.22;
  return (
    <group>
      {corners.map((c, i) => (
        <Line key={i} points={[apex, c]} color={color} lineWidth={lit ? 1.6 : 1} transparent opacity={opacity} />
      ))}
      {lit && <Line points={foot} color={color} lineWidth={1.4} transparent opacity={0.8} />}
      <mesh position={apex}>
        <boxGeometry args={[0.5, 0.35, 0.5]} />
        <meshBasicMaterial color={color} />
      </mesh>
    </group>
  );
}

function ScanMarkers() {
  const { parcel, selection, select, mode } = useWorkspace();
  const scans = parcel.data?.scans ?? [];
  if (mode === "people") return null;
  return (
    <group>
      {scans.map((s) => {
        const sp = scanPoint(s.station_id ?? s.device_id);
        const z = hubZone(s.zone_id);
        const xy: [number, number] | null = sp ? [sp.position_m[0], sp.position_m[1]] : z ? centroid(z.polygons[0]) : null;
        if (!xy) return null;
        const sel = selection?.kind === "scan" && selection.scanId === s.scan_event_id;
        const pos = r3([xy[0], xy[1], (sp?.position_m[2] ?? 1) + 0.6]);
        return (
          <group key={s.scan_event_id}>
            <mesh position={pos} rotation={[0, Math.PI / 4, 0]}
              onClick={(e: ThreeEvent<MouseEvent>) => { e.stopPropagation(); select({ kind: "scan", scanId: s.scan_event_id }); }}>
              <octahedronGeometry args={[sel ? 0.55 : 0.42]} />
              <meshBasicMaterial color={sel ? "#ffffff" : "#e2e8f0"} />
            </mesh>
          </group>
        );
      })}
    </group>
  );
}

/** The six scan checkpoints (lib/checkpoints, the same as the Answer's strip), placed on their scanners from the hub
 *  plan: one pin each, green for a scan, grey dashed for no scan, red where the records and the cameras disagree,
 *  joined in order by one line. */
const CK_COLOUR: Record<Checkpoint["state"], string> = { scanned: "#4ade80", missing: "#8a939c", unscanned: "#f87171", conflict: "#f87171" };

function useCheckpoints(): (Checkpoint & { at: Vec3 })[] {
  const { caseId, journey } = useWorkspace();
  const cf = useResource<{ objects: { records?: CaseRecord[] }[] }>(`/v1/cases/${caseId}/conflicts`);
  return useMemo(() => {
    const j = journey.data?.objects[0];
    if (!j) return [];
    const dockSeen = j.observed_segments > 0
      ? j.segments.some((sg) => sg.kind === "observed" && "points" in sg && sg.points.some((q) => q.zone_id === "zone_Z12"))
      : undefined;
    const waybill = j.identity_keys.find((k) => k.startsWith("carrier_waybill:"))?.split(":")[1] ?? null;
    return buildCheckpoints({ scans: j.scans, records: cf.data?.objects[0]?.records ?? [], barcode: waybill, truckSeen: dockSeen })
      .flatMap((c) => {
        const sp = c.point ? scanPoint(c.point) : undefined;
        return sp ? [{ ...c, at: [sp.position_m[0], sp.position_m[1], sp.position_m[2]] as Vec3 }] : [];
      });
  }, [journey.data, cf.data]);
}

function CheckpointPins() {
  const { mode } = useWorkspace();
  const cps = useCheckpoints();
  if (mode === "people" || !cps.length) return null;
  const head = (c: { at: Vec3 }) => r3([c.at[0], c.at[1], c.at[2] + 2.4]);
  return (
    <group>
      {cps.slice(1).map((c, i) => {
        const a = cps[i];
        const gapState = (x: Checkpoint) => x.state === "missing" || x.state === "unscanned";
        const dashed = gapState(a) || gapState(c);
        return (
          <Line key={`ck-l-${c.id}`} points={[head(a), head(c)]} color={c.state === "conflict" ? CK_COLOUR.conflict : dashed ? CK_COLOUR.missing : CK_COLOUR.scanned}
            lineWidth={2.5} dashed={dashed} dashSize={0.6} gapSize={0.45} onUpdate={onTop} />
        );
      })}
      {cps.map((c) => (
        <group key={`ck-${c.id}`}>
          <mesh position={r3([c.at[0], c.at[1], c.at[2] + 1.2])} onUpdate={onTop}>
            <cylinderGeometry args={[0.05, 0.05, 2.4, 8]} />
            <meshBasicMaterial color={CK_COLOUR[c.state]} transparent opacity={c.state === "missing" || c.state === "unscanned" ? 0.45 : 0.9} />
          </mesh>
          <mesh position={head(c)} onUpdate={onTop}>
            <sphereGeometry args={[c.state === "missing" || c.state === "unscanned" ? 0.42 : 0.5, 20, 14]} />
            <meshBasicMaterial color={CK_COLOUR[c.state]} wireframe={c.state === "missing" || c.state === "unscanned"} />
          </mesh>
        </group>
      ))}
    </group>
  );
}

/** Evidence lines draw over the hub geometry (a parcel on the 1.5 m sorter deck must not hide its own trace). */
function onTop(o: THREE.Object3D) {
  o.renderOrder = 10;
  const m = (o as THREE.Mesh).material as THREE.Material | undefined;
  if (m) { m.depthTest = false; m.transparent = true; }
}

const LOOP = HUB.machines.loop;
const CHUTES = HUB.machines.chutes;
const BELTS = HUB.machines.conveyors; // every infeed line in the site plan (A, B, ...)
/** Draw height of an observation: its own z when the backend gives one, else the surface under its floor point. */
function zOf(p: ReplayPoint): number {
  const ry = p.renderer_xyz_y_up?.[1] ?? 0;
  return ry > 0.01 ? ry : surfaceHeight(LOOP, CHUTES, p.floor_xy_m!, BELTS);
}
const at3 = (p: ReplayPoint) => r3([p.floor_xy_m![0], p.floor_xy_m![1], zOf(p)]);

function Arrow({ from, to }: { from: ReplayPoint; to: ReplayPoint }) {
  const a = at3(from);
  const b = at3(to);
  const dir = b.clone().sub(a).normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  return (
    <mesh position={b} quaternion={q} onUpdate={onTop}>
      <coneGeometry args={[0.45, 1.1, 16]} />
      <meshBasicMaterial color="#4ade80" />
    </mesh>
  );
}

/** Amber dashed hypothesis, routed along known conveyance. Points are memoised: drei's Line rebuilds its geometry
 * when the points array changes, and a rebuilt geometry loses the dash distances until the next layout pass. */
function HypothesisRoute({ from, to, onSelect }: { from: ReplayPoint; to: ReplayPoint; onSelect: () => void }) {
  const pts = useMemo(() => routeLink(LOOP, CHUTES, from.floor_xy_m!, to.floor_xy_m!, 1.0, BELTS).points
    .map((q) => r3([q[0], q[1], surfaceHeight(LOOP, CHUTES, q, BELTS) + 0.45])), [from, to]);
  const ref = useRef<{ computeLineDistances: () => void } | null>(null);
  const invalidate = useThree((st) => st.invalidate);
  useEffect(() => {
    // the geometry is attached after drei's own layout effect ran, so compute dash distances once more here
    const id = requestAnimationFrame(() => { ref.current?.computeLineDistances(); invalidate(); });
    return () => cancelAnimationFrame(id);
  }, [pts, invalidate]);
  return (
    <group>
      {/* dark backing so the amber dashes read against the yellow loop guarding */}
      <Line points={pts} color="#140f05" lineWidth={8} onUpdate={(o: THREE.Object3D) => { onTop(o); o.renderOrder = 9; }} />
      <Line ref={ref as never} points={pts} color="#fbbf24" lineWidth={4} onUpdate={(o: THREE.Object3D) => { onTop(o); o.renderOrder = 11; }}
        dashed dashSize={0.6} gapSize={0.4} onClick={(e) => { e.stopPropagation(); onSelect(); }} />
    </group>
  );
}

function TraceLines() {
  const { replay, select, selection, mode, focusOn } = useWorkspace();
  const traces = useMemo(() => (replay.data?.objects ?? []).map(buildTrace), [replay.data]);
  const framed = useRef<unknown>(null);
  useEffect(() => {
    // Frame the observed trace once when it first arrives (Object / All modes); never re-frame on every refresh.
    if (mode === "people" || framed.current === replay.data) return;
    const pts = traces.flatMap((t) => [
      ...[...t.solid.flatMap((r) => r.points), ...t.singles].map((p) => p.floor_xy_m!),
      ...t.dashed.flatMap((d) => routeLink(LOOP, CHUTES, d.from.floor_xy_m!, d.to.floor_xy_m!, 1.0, BELTS).points),
    ]);
    if (!pts.length) return;
    framed.current = replay.data;
    const xs = pts.map((p) => p[0]);
    const ys = pts.map((p) => p[1]);
    const cx = (Math.min(...xs) + Math.max(...xs)) / 2;
    const cy = (Math.min(...ys) + Math.max(...ys)) / 2;
    focusOn([cx, cy], Math.max(8, Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)) / 2 + 4));
  }, [traces, mode, replay.data, focusOn]);
  if (mode === "people") return null;
  return (
    <group>
      {traces.map((t, ti) => (
        <group key={ti}>
          {t.solid.map((run) => (
            <Line key={run.key} points={run.points.map(at3)}
              color="#4ade80" lineWidth={5} onUpdate={onTop}
              onClick={(e) => {
                e.stopPropagation();
                // nearest observation on this run -> its exact source frame
                const hit = e.point;
                let best = run.points[0];
                let bd = Infinity;
                for (const p of run.points) {
                  const d = at3(p).distanceTo(hit);
                  if (d < bd) { bd = d; best = p; }
                }
                select({ kind: "observation", observationId: best.observation_id });
              }} />
          ))}
          {t.solid.map((run) => {
            const n = run.points.length;
            return <Arrow key={`a${run.key}`} from={run.points[n - 2]} to={run.points[n - 1]} />;
          })}
          {t.dashed.map((d) => (
            <HypothesisRoute key={d.key} from={d.from} to={d.to}
              onSelect={() => select({ kind: "observation", observationId: d.to.observation_id })} />
          ))}
          {[...t.solid.flatMap((r) => r.points), ...t.singles].filter((p) => p.uncertainty_radius_m).map((p) => {
            const sel = selection?.kind === "observation" && selection.observationId === p.observation_id;
            if (!sel) return null;
            return (
              <mesh key={p.observation_id} position={r3([p.floor_xy_m![0], p.floor_xy_m![1], zOf(p) - 0.02])} rotation={[-Math.PI / 2, 0, 0]}>
                <ringGeometry args={[Math.max(0.05, p.uncertainty_radius_m! - 0.06), p.uncertainty_radius_m!, 48]} />
                <meshBasicMaterial color="#60a5fa" transparent opacity={0.9} />
              </mesh>
            );
          })}
        </group>
      ))}
    </group>
  );
}

function LastConfirmed() {
  const { lastSeen, parcel } = useWorkspace();
  const lc = lastSeen.data?.[0]?.last_confident;
  if (!lc) return null;
  const scan = parcel.data?.scans.find((s) => s.scan_event_id === lc.evidence_id);
  const sp = scan ? scanPoint(scan.station_id ?? scan.device_id) : null;
  if (!sp) return null;
  const pos = r3([sp.position_m[0], sp.position_m[1], 0.07]);
  return (
    <group>
      <mesh position={pos} rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.1, 1.3, 64]} />
        <meshBasicMaterial color="#ffffff" />
      </mesh>
    </group>
  );
}

function CameraRig({ reduced }: { reduced: boolean }) {
  const { focus, parcel } = useWorkspace();
  const controls = useRef<OrbitControlsImpl>(null);
  const { camera, invalidate, size } = useThree();
  const aspect = size.width / Math.max(1, size.height);
  const home = useMemo(() => {
    if (aspect < 0.9) {
      // portrait (phone): look along the hall's long axis from the west so the 60 m side runs up the screen
      const k = Math.max(1, 0.7 / aspect);
      return { target: r3([31, 20, 0]), pos: r3([31 - 40 * k, 20, 58 * k]) };
    }
    const k = Math.max(1, 1.25 / aspect);
    // same orientation as the 2D plan (north away, inbound docks on the left), a calm 3/4 view framed on the trail
    const pts = (parcel.data?.scans ?? []).flatMap((s) => { const sp = scanPoint(s.station_id ?? s.device_id); return sp ? [sp.position_m] : []; });
    if (pts.length) {
      const xs = pts.map((p) => p[0]);
      const ys = pts.map((p) => p[1]);
      const [cx, cy] = [(Math.min(...xs) + Math.max(...xs)) / 2, (Math.min(...ys) + Math.max(...ys)) / 2];
      const span = Math.max(22, Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)) * k;
      return { target: r3([cx, cy, 0]), pos: r3([cx, cy - span * 1.05, span * 1.15]) };
    }
    return { target: r3([30, 20, 0]), pos: r3([30, 20 - 52 * k, 52 * k]) };
  }, [aspect, parcel.data]);
  useEffect(() => {
    camera.position.copy(home.pos);
    controls.current?.target.copy(home.target);
    controls.current?.update();
  }, [camera, home]);
  useEffect(() => {
    const c = controls.current;
    if (!c || focus.id === 0) return;
    const target = focus.site_xy ? r3([focus.site_xy[0], focus.site_xy[1], 0]) : home.target;
    const dist = focus.site_xy ? Math.max(10, focus.radius_m * 2.2) : null;
    const endPos = dist ? target.clone().add(new THREE.Vector3(0, dist * 0.9, dist * 0.75)) : home.pos;
    const t0 = c.target.clone();
    const p0 = camera.position.clone();
    if (reduced) {
      c.target.copy(target); camera.position.copy(endPos); c.update(); invalidate();
      return;
    }
    let raf = 0;
    const start = performance.now();
    const step = (now: number) => {
      const k = Math.min(1, (now - start) / 550);
      const e = 1 - Math.pow(1 - k, 3);
      c.target.lerpVectors(t0, target, e);
      camera.position.lerpVectors(p0, endPos, e);
      c.update();
      invalidate();
      if (k < 1) raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
    return () => cancelAnimationFrame(raf);
  }, [focus, camera, home, reduced, invalidate]);
  // orbit stays above the floor and inside the building's scale (no flipping, no flying off)
  return <OrbitControls ref={controls} makeDefault enableDamping={!reduced} maxPolarAngle={Math.PI / 2.3}
    minDistance={6} maxDistance={95} />;
}

/** Keyboard control for the canvas container: arrows pan, +/- zoom, R resets (PRD §19.4 keyboard control). */
function KeyboardNav({ el }: { el: HTMLElement | null }) {
  const { camera, controls, invalidate } = useThree() as unknown as { camera: THREE.Camera; controls: OrbitControlsImpl | null;
    invalidate: () => void };
  const { focusOn } = useWorkspace();
  useEffect(() => {
    if (!el) return;
    const onKey = (e: KeyboardEvent) => {
      if (!controls) return;
      const step = e.shiftKey ? 6 : 2;
      const fwd = new THREE.Vector3().subVectors(controls.target, camera.position).setY(0).normalize();
      const right = new THREE.Vector3().crossVectors(fwd, new THREE.Vector3(0, 1, 0));
      let move: THREE.Vector3 | null = null;
      if (e.key === "ArrowUp") move = fwd.multiplyScalar(step);
      if (e.key === "ArrowDown") move = fwd.multiplyScalar(-step);
      if (e.key === "ArrowLeft") move = right.multiplyScalar(-step);
      if (e.key === "ArrowRight") move = right.multiplyScalar(step);
      if (move) {
        controls.target.add(move); camera.position.add(move);
      } else if (e.key === "+" || e.key === "=" || e.key === "-") {
        const dir = new THREE.Vector3().subVectors(camera.position, controls.target);
        dir.multiplyScalar(e.key === "-" ? 1.2 : 1 / 1.2);
        camera.position.copy(controls.target).add(dir);
      } else if (e.key === "r" || e.key === "R") {
        focusOn(null);
      } else return;
      e.preventDefault();
      controls.update();
      invalidate();
    };
    el.addEventListener("keydown", onKey);
    return () => el.removeEventListener("keydown", onKey);
  }, [el, camera, controls, invalidate, focusOn]);
  return null;
}

interface Label { key: string; site: Vec3; text: string; tone: "scan" | "cam" | "last" | "sel" | "land" | "ck-scanned" | "ck-missing" | "ck-unscanned" | "ck-conflict" }
interface Placed { key: string; x: number; y: number; ay: number; text: string; tone: Label["tone"] }

const PRIORITY: Record<Label["tone"], number> = { sel: 0, last: 1, "ck-conflict": 1, "ck-scanned": 2, "ck-missing": 2, "ck-unscanned": 1, cam: 3, scan: 4, land: 5 };

/** Landmarks that keep the user oriented (design_sprint §H), placed at their zone's centre, above the racks. */
const LANDMARKS: [string, string][] = [["Z01", "Inbound docks 01–06"], ["Z12", "Outbound docks 07–12"], ["Z05", "Sorter"],
  ["Z06", "Chutes"], ["Z10", "Cage staging"], ["Z11", "Exception store"]];
const LANDMARK_LABELS: Label[] = LANDMARKS.flatMap(([id, text]) => {
  const z = HUB.zones.find((x) => x.id === id);
  if (!z?.polygons[0]) return [];
  const [x, y] = centroid(z.polygons[0]);
  return [{ key: `land-${id}`, site: [x, y, 3.2] as Vec3, text, tone: "land" as const }];
});

/** Screen-space de-overlap: higher-priority labels keep their place; others stack upward with a leader line. */
export function declutter(items: Omit<Placed, "ay">[], width = Infinity): Placed[] {
  const boxes: { l: number; r: number; t: number; b: number }[] = [];
  const out: Placed[] = [];
  for (const raw of [...items].sort((a, b) => PRIORITY[a.tone] - PRIORITY[b.tone])) {
    const w = raw.text.length * 6.6 + 22;
    const h = 24;
    const it = { ...raw, x: Math.min(Math.max(raw.x, w / 2 + 4), width - w / 2 - 4) }; // keep the chip inside the canvas
    const below = it.tone === "last"; // the last-confirmed tag hangs under its ring
    let placedAt: number | null = null;
    for (let k = 0; k < 6 && placedAt === null; k++) {
      const y = below ? it.y + 8 + k * (h + 2) : it.y - k * (h + 2);
      const box = below ? { l: it.x - w / 2, r: it.x + w / 2, t: y, b: y + h } : { l: it.x - w / 2, r: it.x + w / 2, t: y - h, b: y };
      if (!boxes.some((o) => box.l < o.r && box.r > o.l && box.t < o.b && box.b > o.t)) {
        boxes.push(box);
        placedAt = y;
      }
    }
    if (placedAt !== null) out.push({ ...it, ay: it.y, y: placedAt });
  }
  return out;
}

/** Turns the compass needle so N points to site north on screen, whenever the view changes (design_sprint §H). */
function CompassSync({ needle }: { needle: RefObject<HTMLSpanElement | null> }) {
  const { camera, controls } = useThree() as unknown as { camera: THREE.Camera; controls: OrbitControlsImpl | null };
  useEffect(() => {
    if (!controls) return;
    const run = () => {
      // eslint-disable-next-line react-hooks/immutability -- the needle turns on every orbit frame: a direct transform, no re-render
      const el = needle.current;
      if (!el) return;
      const a = controls.target.clone().project(camera);
      const t = controls.target.clone().add(r3([0, 10, 0]).sub(r3([0, 0, 0]))).project(camera);
      el.style.transform = `rotate(${Math.atan2(t.x - a.x, t.y - a.y)}rad)`;
    };
    run();
    controls.addEventListener("change", run);
    return () => controls.removeEventListener("change", run);
  }, [needle, controls, camera]);
  return null;
}

/** Projects label anchors to screen space whenever the view changes; labels are plain DOM over the canvas. */
function Projector({ labels, onPlace }: { labels: Label[]; onPlace: (p: Placed[]) => void }) {
  const { camera, size, controls } = useThree() as unknown as { camera: THREE.Camera; size: { width: number; height: number };
    controls: OrbitControlsImpl | null };
  useEffect(() => {
    let raf = 0;
    const run = () => {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(() => {
        const v = new THREE.Vector3();
        onPlace(declutter(labels.flatMap((l) => {
          v.copy(r3(l.site)).project(camera);
          if (v.z > 1 || v.x < -1.1 || v.x > 1.1 || v.y < -1.1 || v.y > 1.1) return [];
          return [{ key: l.key, text: l.text, tone: l.tone, x: (v.x + 1) / 2 * size.width, y: (1 - v.y) / 2 * size.height }];
        }), size.width));
      });
    };
    run();
    controls?.addEventListener("change", run);
    return () => { controls?.removeEventListener("change", run); cancelAnimationFrame(raf); };
  }, [labels, camera, size, controls, onPlace]);
  return null;
}

function useLabels(): Label[] {
  const { parcel, litCameras, selection, lastSeen, mode } = useWorkspace();
  const cps = useCheckpoints();
  return useMemo(() => {
    const out: Label[] = [];
    if (mode !== "people") {
      cps.forEach((c, i) => out.push({
        key: `ck-${c.id}`, site: [c.at[0], c.at[1], c.at[2] + 3.4],
        text: c.state === "missing" || c.state === "unscanned" ? `${i + 1} ${c.label} · ${c.none.charAt(0).toLowerCase()}${c.none.slice(1)}` : c.state === "conflict" ? `${c.label} · ${c.records?.replace(/^Records: /, "")} · never seen there` : `${i + 1} ${c.label}${c.t ? ` · ${fmtTime(c.t, false)}` : ""}`,
        tone: `ck-${c.state}` as Label["tone"],
      }));
    }
    if (mode !== "people") {
      // the trail's two ends say where it starts and stops; a middle scan gets a chip only when it is picked
      const lc = lastSeen.data?.[0]?.last_confident?.evidence_id;
      const scans = parcel.data?.scans ?? [];
      scans.forEach((s, i) => {
        const sp = scanPoint(s.station_id ?? s.device_id);
        if (!sp) return;
        const sel = selection?.kind === "scan" && selection.scanId === s.scan_event_id;
        if (s.scan_event_id === lc) {
          out.push({ key: "last", site: [sp.position_m[0], sp.position_m[1], 0.1], text: `Last seen ${fmtTime(s.time, false)}`, tone: "last" });
        } else if ((i === 0 && !cps.length) || sel) { // the checkpoint pins already name the first scan
          out.push({ key: s.scan_event_id, site: [sp.position_m[0], sp.position_m[1], sp.position_m[2] + 1.4],
            text: i === 0 && !sel ? `Scanned ${fmtTime(s.time, false)}` : `${describeScan(s).title} · ${fmtTime(s.time, false)}`, tone: sel ? "sel" : "scan" });
        }
      });
    }
    for (const id of litCameras) {
      const c = HUB.cameras.find((x) => x.id === id);
      if (c) out.push({ key: `cam-${id}`, site: [c.position_m[0], c.position_m[1], c.height_m + 0.6], text: id.replace("_", " "), tone: "cam" });
    }
    return [...out, ...LANDMARK_LABELS];
  }, [parcel.data, litCameras, selection, lastSeen.data, mode, cps]);
}

export default function Scene3D() {
  const { litCameras, cameras, focusOn } = useWorkspace();
  const reduced = usePrefersReducedMotion();
  const [ready, setReady] = useState(false);
  const [el, setEl] = useState<HTMLDivElement | null>(null);
  const labels = useLabels();
  const [placed, setPlaced] = useState<Placed[]>([]);
  const needle = useRef<HTMLSpanElement>(null);
  const covered = useMemo(() => new Set((cameras.data ?? []).filter((c) => c.coverage.length)
    .map((c) => c.camera.camera_id.replace(/^cam_/, ""))), [cameras.data]);
  return (
    <div ref={setEl} className="sp-scene" tabIndex={0} role="application" data-ready={ready ? "true" : "false"}
      aria-label="3D hub scene. Arrow keys pan, plus and minus zoom, R resets the view. Click a marker or line to open its source.">
      <Canvas frameloop="demand" dpr={[1, 1.75]} gl={{ antialias: true, preserveDrawingBuffer: true }}
        camera={{ fov: 42, near: 0.2, far: 600 }} onPointerMissed={() => {}}>
        <color attach="background" args={["#0e1012"]} />
        <hemisphereLight args={["#e8edf2", "#2a2f35", 1.6]} />
        <directionalLight position={[30, 60, 20]} intensity={1.4} />
        <Suspense fallback={null}>
          <HubModel onReady={() => setReady(true)} />
        </Suspense>
        <ZoneOverlay />
        {HUB.cameras.map((c) => <CameraCone key={c.id} cam={c} lit={litCameras.includes(c.id)} covered={covered.has(c.id)} />)}
        <ScanMarkers />
        <CheckpointPins />
        <TraceLines />
        <LastConfirmed />
        <CameraRig reduced={reduced} />
        <KeyboardNav el={el} />
        <Projector labels={labels} onPlace={setPlaced} />
        <CompassSync needle={needle} />
      </Canvas>
      <div className="sp-scene-labels" aria-hidden>
        {placed.map((p) => (
          <span key={p.key}>
            {Math.abs(p.y - p.ay) > 2 && p.tone !== "last" && (
              <span className="sp-leader" style={{ left: p.x, top: p.y, height: p.ay - p.y }} />
            )}
            <span className="sp-chip" data-tone={p.tone} style={{ left: p.x, top: p.y }}>{p.text}</span>
          </span>
        ))}
      </div>
      {!ready && <div className="sp-scene-loading"><SpoorLoader label="Loading the 3D hub" size={56} /></div>}
      <div className="sp-scene-tools">
        <button className="sp-btn sp-btn-sm" onClick={() => focusOn(null)}>Reset view</button>
      </div>
      <div className="sp-compass" aria-label="Compass" role="img">
        <span ref={needle} className="sp-compass-needle"><span className="sp-compass-n">N</span></span>
      </div>
    </div>
  );
}

useGLTF.preload("/hub.glb", "/draco/");
